function messagesAt(index: 0 | 1 | 2 | 3): Record<string, string> {
  return Object.fromEntries(
    Object.entries(rows).map(([key, translations]) => [key, translations[index]]),
  );
}

export const usageMessages: Record<SupportedLocale, Record<string, string>> = {
  'zh-CN': messagesAt(0),
  en: messagesAt(1),
  ja: messagesAt(2),
  ko: messagesAt(3),
};
